<template><q-page class="q-pa-lg"><div class="overview-hero q-pa-lg q-mb-lg"><div class="row justify-between items-center"><div><q-badge color="white" text-color="primary" label="AHY WATER STATION"/><h1 class="text-h4 text-weight-bold q-mb-sm">A clear view of your station.</h1><p class="q-mb-none">Welcome, {{staff?.name}}. Here is how business is flowing today.</p></div><q-btn unelevated color="white" text-color="primary" icon="add_shopping_cart" label="New sale" to="/pos" class="q-mt-md"/></div></div>
<q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" role="alert">{{error}}<template #action><q-btn flat label="Retry" @click="load"/></template></q-banner><q-linear-progress v-if="loading" indeterminate class="q-mb-md"/>
<div class="row q-col-gutter-md q-mb-lg"><div v-for="s in cards" :key="s.label" class="col-12 col-sm-6 col-xl-3"><q-card flat bordered class="q-pa-lg"><div class="row justify-between"><span class="text-grey-7">{{s.label}}</span><q-icon :name="s.icon" color="primary" size="24px"/></div><div class="text-h4 text-weight-bold q-mt-md">{{s.value}}</div><div class="text-caption text-grey-7 q-mt-sm">{{s.caption}}</div></q-card></div></div>
<div class="row q-col-gutter-lg"><div class="col-12 col-md-7"><q-card flat bordered><q-card-section class="row items-center justify-between"><span class="text-h6">Recent transactions</span><q-btn flat color="primary" label="View all" to="/sales"/></q-card-section><q-list separator><q-item v-for="o in stats.recent_orders" :key="o.id"><q-item-section avatar><q-avatar color="blue-1" text-color="primary" icon="receipt_long"/></q-item-section><q-item-section><q-item-label>{{o.customer_name}}</q-item-label><q-item-label caption>{{o.receipt_number||`Legacy #${o.id}`}} · {{dateTime(o.created_at)}}</q-item-label></q-item-section><q-item-section side><div class="text-weight-bold">{{money(o.total_amount)}}</div><q-badge :color="o.status==='Completed'?'teal':'negative'">{{o.status}}</q-badge></q-item-section></q-item></q-list><q-card-section v-if="!stats.recent_orders.length" class="text-grey-7">Your first completed sale will appear here.</q-card-section></q-card></div>
<div class="col-12 col-md-5"><q-card flat bordered><q-card-section class="row justify-between items-center"><span class="text-h6">Stock alerts</span><q-btn flat label="Inventory" color="primary" to="/inventory"/></q-card-section><q-list separator><q-item v-for="p in stats.stock_alerts" :key="p.id"><q-item-section>{{p.name}}</q-item-section><q-item-section side><q-badge :color="p.stock===0?'negative':'orange-9'">{{p.stock}} left</q-badge></q-item-section></q-item></q-list><q-card-section v-if="!stats.stock_alerts.length" class="text-grey-7">No stock alerts.</q-card-section></q-card><q-card flat bordered class="q-pa-lg q-mt-md"><div class="text-h6">Deliveries in progress</div><div class="text-h3 text-primary q-my-md">{{stats.pending_deliveries}}</div><q-btn outline color="primary" label="Manage deliveries" to="/deliveries"/></q-card></div></div>
<div class="row justify-between items-center q-mt-lg text-caption text-grey-7"><span>Completed sales only count toward revenue. {{stats.total_products}} active products · {{stats.total_orders}} recorded orders.</span><q-btn flat dense icon="refresh" label="Refresh overview" :loading="loading" @click="load"/></div>
</q-page></template>
<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import api,{errorMessage}from'../services/api';import{money,dateTime}from'../services/format';import{staff}from'../services/auth'
const stats=ref({total_products:0,total_orders:0,total_sales:0,today_sales:0,today_orders:0,low_stock:0,out_of_stock:0,pending_deliveries:0,recent_orders:[] as any[],stock_alerts:[] as any[]}),loading=ref(false),error=ref('')
const cards=computed(()=>[{label:"Today's sales",value:money(stats.value.today_sales),caption:`${stats.value.today_orders} completed orders today`,icon:'payments'},{label:'All-time sales',value:money(stats.value.total_sales),caption:'Completed transactions',icon:'trending_up'},{label:'Low stock',value:stats.value.low_stock,caption:'Products at the reorder level',icon:'inventory_2'},{label:'Out of stock',value:stats.value.out_of_stock,caption:'Active products needing a refill',icon:'warning_amber'}])
async function load(){loading.value=true;error.value='';try{stats.value=(await api.get('/dashboard')).data}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}onMounted(load)
</script>
<style scoped>.overview-hero{border-radius:20px;background:linear-gradient(120deg,#07516d,#087ca6);color:white}</style>
